import random
from fractions import Fraction


def coupon_expectation(n):
    return sum(Fraction(n, k) for k in range(1, n + 1))


def coupon_sim(n, trials, seed):
    rng = random.Random(seed)
    total = 0
    for _ in range(trials):
        seen = set()
        draws = 0
        while len(seen) < n:
            seen.add(rng.randrange(n))
            draws += 1
        total += draws
    return total / trials
